entries.answer:
Az alábbi alkalmazás Flask backenddel és egy egyszerű klienssel hívja a Claude Opus 4.5 modellt a Bedrock InvokeModel végpontján, az Anthropic Messages API sémájával és az AWS_BEARER_TOKEN_BEDROCK környezeti változón keresztüli API-kulcsos hitelesítéssel. A modelId a Bedrock katalógus szerinti azonosítót használja (anthropic.claude-opus-4-5-20251101-v1:0), a régió pedig us-east-1-re állítható, ami megfelel a Bedrock runtime hostolási mintájának.[1][2][3]

## Teljes kódok

```python
# main.py
import os
import json
import http.client
from flask import Flask, request, jsonify, send_from_directory

app = Flask(__name__, static_folder='.', static_url_path='')

def normalize_messages(msgs):
    out = []
    for m in msgs:
        role = m.get("role", "").strip()
        content = m.get("content", "")
        if isinstance(content, list):
            parts = []
            for c in content:
                if isinstance(c, dict) and c.get("type") == "text" and isinstance(c.get("text"), str):
                    parts.append({"type": "text", "text": c["text"]})
                elif isinstance(c, str):
                    parts.append({"type": "text", "text": c})
            if not parts:
                parts = [{"type": "text", "text": ""}]
            out.append({"role": role, "content": parts})
        elif isinstance(content, str):
            out.append({"role": role, "content": [{"type": "text", "text": content}]})
        else:
            out.append({"role": role, "content": [{"type": "text", "text": ""}]})
    return out

def invoke_bedrock(messages, system=None, max_tokens=1024, temperature=0.7, top_p=None, stop_sequences=None, region=None, model_id=None, api_key=None, timeout=3600):
    host = f"bedrock-runtime.{region}.amazonaws.com"
    path = f"/model/{model_id}/invoke"
    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "messages": normalize_messages(messages)
    }
    if system is not None and isinstance(system, str) and len(system) > 0:
        body["system"] = system
    if temperature is not None:
        body["temperature"] = float(temperature)
    if top_p is not None:
        body["top_p"] = float(top_p)
    if stop_sequences is not None and isinstance(stop_sequences, list):
        body["stop_sequences"] = stop_sequences
    payload = json.dumps(body)
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": f"Bearer {api_key}"
    }
    conn = http.client.HTTPSConnection(host, timeout=timeout)
    conn.request("POST", path, body=payload, headers=headers)
    resp = conn.getresponse()
    data = resp.read()
    status = resp.status
    content_type = resp.getheader("Content-Type", "application/json")
    conn.close()
    if status != 200:
        try:
            err = json.loads(data.decode("utf-8"))
        except Exception:
            err = {"message": data.decode("utf-8", errors="ignore")}
        return {"ok": False, "status": status, "error": err}
    if "application/json" in content_type:
        parsed = json.loads(data.decode("utf-8"))
        return {"ok": True, "data": parsed}
    return {"ok": True, "data": {"raw": data.decode("utf-8", errors="ignore")}}

@app.route("/", methods=["GET"])
def root():
    return send_from_directory(os.getcwd(), "index.html")

@app.route("/api/chat", methods=["POST"])
def api_chat():
    api_key = os.environ.get("AWS_BEARER_TOKEN_BEDROCK", "").strip()
    if not api_key:
        return jsonify({"error": "AWS_BEARER_TOKEN_BEDROCK missing"}), 400
    region = os.environ.get("AWS_REGION", "us-east-1").strip() or "us-east-1"
    model_id = os.environ.get("BEDROCK_MODEL_ID", "anthropic.claude-opus-4-5-20251101-v1:0").strip() or "anthropic.claude-opus-4-5-20251101-v1:0"
    payload = request.get_json(silent=True) or {}
    messages = payload.get("messages") or []
    prompt = payload.get("prompt")
    system = payload.get("system")
    max_tokens = payload.get("max_tokens", 1024)
    temperature = payload.get("temperature", 0.7)
    top_p = payload.get("top_p")
    stop_sequences = payload.get("stop_sequences")
    if not messages and isinstance(prompt, str) and len(prompt) > 0:
        messages = [{"role": "user", "content": prompt}]
    if not isinstance(messages, list) or len(messages) == 0:
        return jsonify({"error": "messages or prompt required"}), 400
    result = invoke_bedrock(messages=messages, system=system, max_tokens=max_tokens, temperature=temperature, top_p=top_p, stop_sequences=stop_sequences, region=region, model_id=model_id, api_key=api_key)
    if not result.get("ok"):
        return jsonify({"error": result.get("error"), "status": result.get("status")}), int(result.get("status") or 500)
    data = result["data"]
    text = ""
    usage = {}
    if isinstance(data, dict):
        if "content" in data and isinstance(data["content"], list):
            parts = []
            for c in data["content"]:
                if isinstance(c, dict) and c.get("type") == "text" and isinstance(c.get("text"), str):
                    parts.append(c["text"])
            text = "".join(parts)
        if "usage" in data and isinstance(data["usage"], dict):
            usage = data["usage"]
        if not text and "raw" in data:
            text = str(data["raw"])
    return jsonify({"output_text": text, "usage": usage, "model_id": model_id, "region": region})

if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    app.run(host="0.0.0.0", port=port)
