            normalized.append(
                {
                    "role": role,
                    "content": parts
                }
            )
        else:
            normalized.append(
                {
                    "role": role,
                    "content": [
                        {
                            "type": "text",
                            "text": str(content)
                        }
                    ]
                }
            )
    return normalized

def invoke_bedrock(messages, system=None, max_tokens=4096, temperature=0.7, top_p=None, stop_sequences=None, region=None, model_id=None, api_key=None, timeout=3600):
    if not api_key or not isinstance(api_key, str) or not api_key.strip():
        return {
            "ok": False,
            "status": 500,
            "error": {
                "message": "Missing AWS_BEARER_TOKEN_BEDROCK"
            }
        }
    if not region or not isinstance(region, str) or not region.strip():
        region = "us-east-1"
    if not model_id or not isinstance(model_id, str) or not model_id.strip():
        model_id = "global.anthropic.claude-opus-4-5-20251101-v1:0"
    host = "bedrock-runtime." + region + ".amazonaws.com"
    path = "/model/" + model_id + "/invoke"
    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "messages": normalize_messages(messages)
    }
    if isinstance(system, str) and system.strip():
        body["system"] = system
    if temperature is not None:
        body["temperature"] = float(temperature)
    if top_p is not None:
        body["top_p"] = float(top_p)
    if isinstance(stop_sequences, list) and len(stop_sequences) > 0:
        body["stop_sequences"] = stop_sequences
    payload = json.dumps(body)
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": "Bearer " + api_key,
        "x-amz-bedrock-api-version": "2023-10-01"
    }
    connection = http.client.HTTPSConnection(host, timeout=timeout)
    try:
        connection.request("POST", path, body=payload, headers=headers)
        response = connection.getresponse()
        status = response.status
        raw_bytes = response.read()
        content_type = response.getheader("Content-Type", "application/json")
    finally:
        connection.close()
    if status != 200:
        try:
            error_body = json.loads(raw_bytes.decode("utf-8"))
        except Exception:
            error_body = {
                "message": raw_bytes.decode("utf-8", errors="ignore")
            }
        return {
            "ok": False,
            "status": status,
            "error": error_body
        }
    if "application/json" in content_type:
        try:
            parsed = json.loads(raw_bytes.decode("utf-8"))
            return {
                "ok": True,
                "data": parsed
            }
        except Exception:
            pass
    return {
        "ok": True,
        "data": {
            "raw": raw_bytes.decode("utf-8", errors="ignore")
        }
    }

@app.route("/", methods=["GET"])
def root():
    return send_from_directory(os.getcwd(), "index.html")

@app.route("/api/chat", methods=["POST"])
def api_chat():
    api_key = os.environ.get("AWS_BEARER_TOKEN_BEDROCK", "").strip()
    if not api_key:
        return jsonify({"error": "AWS_BEARER_TOKEN_BEDROCK is not set"}), 500
    region = os.environ.get("AWS_REGION", "us-east-1")
    if not isinstance(region, str) or not region.strip():
        region = "us-east-1"
    model_id = os.environ.get("BEDROCK_MODEL_ID", "global.anthropic.claude-opus-4-5-20251101-v1:0")
    if not isinstance(model_id, str) or not model_id.strip():
        model_id = "global.anthropic.claude-opus-4-5-20251101-v1:0"
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        payload = {}
    messages = payload.get("messages")
    prompt = payload.get("prompt")
    system = payload.get("system")
    max_tokens = payload.get("max_tokens", 4096)
    temperature = payload.get("temperature", 0.7)
    top_p = payload.get("top_p")
    stop_sequences = payload.get("stop_sequences")
    if not isinstance(messages, list) or len(messages) == 0:
        if isinstance(prompt, str) and prompt.strip():
            messages = [
                {
                    "role": "user",
                    "content": prompt
                }
            ]
        else:
            return jsonify({"error": "messages or prompt is required"}), 400
    result = invoke_bedrock(
        messages=messages,
        system=system,
        max_tokens=max_tokens,
        temperature=temperature,
        top_p=top_p,
        stop_sequences=stop_sequences,
        region=region,
        model_id=model_id,
        api_key=api_key
    )
    if not result.get("ok"):
        status = int(result.get("status") or 500)
        return jsonify({"error": result.get("error"), "status": status}), status
    data = result.get("data")
    text = ""
    usage = {}
    if isinstance(data, dict):
        content_value = data.get("content")
        if isinstance(content_value, list):
            parts = []
            for item in content_value:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append(item["text"])
            text = "".join(parts)
        usage_value = data.get("usage")
        if isinstance(usage_value, dict):
            usage = usage_value
        if not text and isinstance(data.get("raw"), str):
            text = data["raw"]
    else:
        text = str(data)
    return jsonify(
        {
            "output_text": text,
            "usage": usage,
            "model_id": model_id,
            "region": region
        }
    )

if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    app.run(host="0.0.0.0", port=port)
