import os
import json
import http.client
from flask import Flask, request, jsonify, send_from_directory

app = Flask(__name__, static_folder=".", static_url_path="")

def supermemory_store(content):
    api_key = os.environ.get("SUPERMEMORY_API_KEY", "").strip()
    if not api_key:
        return
    host = "api.supermemory.ai"
    headers = {
        "Content-Type": "application/json",
        "Authorization": "Bearer " + api_key
    }
    body = {
        "content": content,
        "metadata": {"source": "claude-opus-4-5-app"}
    }
    conn = http.client.HTTPSConnection(host)
    try:
        conn.request("POST", "/v1/memories", body=json.dumps(body), headers=headers)
        conn.getresponse().read()
    except Exception:
        pass
    finally:
        conn.close()

def supermemory_retrieve(query):
    api_key = os.environ.get("SUPERMEMORY_API_KEY", "").strip()
    if not api_key:
        return ""
    host = "api.supermemory.ai"
    headers = {
        "Content-Type": "application/json",
        "Authorization": "Bearer " + api_key
    }
    body = {
        "query": query,
        "limit": 100
    }
    conn = http.client.HTTPSConnection(host)
    try:
        conn.request("POST", "/v1/search", body=json.dumps(body), headers=headers)
        resp = conn.getresponse()
        data = json.loads(resp.read().decode("utf-8"))
        hits = data.get("hits", [])
        return "\n---\n".join([h.get("content", "") for h in hits if h.get("content")])
    except Exception:
        return ""
    finally:
        conn.close()

def normalize_messages(messages):
    normalized = []
    for message in messages:
        role = str(message.get("role", "user")).strip() or "user"
        content = message.get("content", "")
        if isinstance(content, str):
            normalized.append({"role": role, "content": [{"type": "text", "text": content}]})
        elif isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append({"type": "text", "text": item["text"]})
                elif isinstance(item, str):
                    parts.append({"type": "text", "text": item})
            if not parts:
                parts.append({"type": "text", "text": ""})
            normalized.append({"role": role, "content": parts})
        else:
            normalized.append({"role": role, "content": [{"type": "text", "text": str(content)}]})
    return normalized

def invoke_bedrock(messages, system=None, max_tokens=64000, temperature=0.7, region=None, model_id=None, api_key=None):
    if not region:
        region = "us-east-1"
    if not model_id:
        model_id = "global.anthropic.claude-opus-4-5-20251101-v1:0"
    host = "bedrock-runtime." + region + ".amazonaws.com"
    path = "/model/" + model_id + "/invoke"
    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "messages": normalize_messages(messages)
    }
    if system:
        body["system"] = system
    body["temperature"] = float(temperature)
    payload = json.dumps(body)
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": "Bearer " + api_key,
        "x-amz-bedrock-api-version": "2023-10-01"
    }
    conn = http.client.HTTPSConnection(host, timeout=3600)
    try:
        conn.request("POST", path, body=payload, headers=headers)
        response = conn.getresponse()
        status = response.status
        raw_bytes = response.read()
    finally:
        conn.close()
    if status != 200:
        return {"ok": False, "status": status, "error": raw_bytes.decode("utf-8")}
    return {"ok": True, "data": json.loads(raw_bytes.decode("utf-8"))}

@app.route("/", methods=["GET"])
def root():
    return send_from_directory(os.getcwd(), "index.html")

@app.route("/api/chat", methods=["POST"])
def api_chat():
    api_key = os.environ.get("AWS_BEARER_TOKEN_BEDROCK", "").strip()
    payload = request.get_json(silent=True) or {}
    messages = payload.get("messages", [])
    system_base = payload.get("system", "")
    user_query = ""
    if messages:
        last_msg = messages[-1].get("content", "")
        user_query = last_msg if isinstance(last_msg, str) else ""
    memories = supermemory_retrieve(user_query)
    full_system = "MAXIMALIS MEMORIA KONTEXTUS:\n" + memories + "\n\nALAP RENDSZERINSTUKCIO:\n" + system_base
    result = invoke_bedrock(
        messages=messages,
        system=full_system,
        max_tokens=64000,
        temperature=0.7,
        api_key=api_key
    )
    if not result.get("ok"):
        return jsonify(result), result.get("status", 500)
    data = result["data"]
    text = "".join([c["text"] for c in data.get("content", []) if c.get("type") == "text"])
    supermemory_store("USER: " + user_query + "\nASSISTANT: " + text)
    return jsonify({"output_text": text, "usage": data.get("usage", {})})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000)
