import os
import json
import time
import uuid
import http.client
from flask import Flask, request, jsonify, send_from_directory

app = Flask(__name__, static_folder=".", static_url_path="")

def _env(name, default=""):
    v = os.environ.get(name)
    if v is None:
        return default
    if isinstance(v, str):
        return v
    return str(v)

def _now_ms():
    return int(time.time() * 1000)

def _safe_json_loads(b):
    try:
        return json.loads(b.decode("utf-8"))
    except Exception:
        try:
            return json.loads(b.decode("utf-8", errors="ignore"))
        except Exception:
            return None

def _http_json(host, method, path, headers, body_obj=None, timeout=60):
    conn = http.client.HTTPSConnection(host, timeout=timeout)
    try:
        body = None
        if body_obj is not None:
            body = json.dumps(body_obj)
        conn.request(method, path, body=body, headers=headers)
        resp = conn.getresponse()
        status = resp.status
        raw = resp.read()
        ctype = resp.getheader("Content-Type", "")
        parsed = None
        if "application/json" in ctype:
            parsed = _safe_json_loads(raw)
        return status, raw, parsed
    finally:
        conn.close()

def _extract_last_user_text(messages):
    if not isinstance(messages, list):
        return ""
    for i in range(len(messages) - 1, -1, -1):
        m = messages[i]
        if not isinstance(m, dict):
            continue
        if str(m.get("role", "")).strip() != "user":
            continue
        c = m.get("content", "")
        if isinstance(c, str):
            return c
        if isinstance(c, list):
            parts = []
            for item in c:
                if isinstance(item, str):
                    parts.append(item)
                elif isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append(item["text"])
            return "".join(parts)
    return ""

def normalize_messages(messages):
    normalized = []
    if not isinstance(messages, list):
        return normalized
    for message in messages:
        if not isinstance(message, dict):
            continue
        role = str(message.get("role", "user")).strip() or "user"
        content = message.get("content", "")
        if isinstance(content, str):
            normalized.append({"role": role, "content": [{"type": "text", "text": content}]})
            continue
        if isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, str):
                    parts.append({"type": "text", "text": item})
                elif isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append({"type": "text", "text": item["text"]})
            if not parts:
                parts.append({"type": "text", "text": ""})
            normalized.append({"role": role, "content": parts})
            continue
        normalized.append({"role": role, "content": [{"type": "text", "text": str(content)}]})
    return normalized

def supermemory_enabled():
    return bool(_env("SUPERMEMORY_API_KEY", "").strip())

def supermemory_container_tag(client_id):
    forced = _env("SUPERMEMORY_CONTAINER_TAG", "").strip()
    if forced:
        return forced
    base = _env("SUPERMEMORY_USER_ID", "").strip()
    if base:
        return base
    if client_id and isinstance(client_id, str) and client_id.strip():
        return "client_" + client_id.strip()
    return "client_" + str(uuid.uuid4())

def supermemory_headers(api_key):
    return {
        "Authorization": "Bearer " + api_key,
        "Content-Type": "application/json",
        "Accept": "application/json"
    }

def supermemory_add_document(api_key, container_tag, text, metadata):
    host = "api.supermemory.ai"
    headers = supermemory_headers(api_key)
    body = {
        "content": text,
        "text": text,
        "data": text,
        "containerTag": container_tag,
        "containerTags": [container_tag],
        "metadata": metadata
    }
    status, raw, parsed = _http_json(host, "POST", "/v3/documents", headers, body_obj=body, timeout=60)
    ok = 200 <= int(status) < 300
