    api_key = _env("SUPERMEMORY_API_KEY", "").strip()
    if not api_key:
        return ""
    container_tag = supermemory_container_tag(client_id)
    limit = int(_env("SUPERMEMORY_SEARCH_LIMIT", "1000") or "1000")
    ok_v4, v4 = supermemory_search_memories_v4(api_key, container_tag, user_query, limit)
    blocks = []
    if ok_v4 and isinstance(v4, dict):
        b = v4.get("blocks", [])
        if isinstance(b, list):
            for x in b:
                if isinstance(x, str) and x.strip():
                    blocks.append(x.strip())
    ok_v3, v3 = supermemory_search_documents_v3(api_key, container_tag, user_query, limit)
    if ok_v3 and isinstance(v3, dict):
        b = v3.get("blocks", [])
        if isinstance(b, list):
            for x in b:
                if isinstance(x, str) and x.strip():
                    blocks.append(x.strip())
    if not blocks:
        return ""
    joined = "\n".join(blocks)
    return "HOSSZU_TAVU_MEMORIA:\n" + joined

def store_turn_to_supermemory(client_id, user_text, assistant_text, request_id):
    api_key = _env("SUPERMEMORY_API_KEY", "").strip()
    if not api_key:
        return
    container_tag = supermemory_container_tag(client_id)
    meta_base = {
        "source": "bedrock-claude-opus-4-5",
        "request_id": request_id,
        "ts_ms": _now_ms()
    }
    if isinstance(user_text, str) and user_text.strip():
        supermemory_add_document(api_key, container_tag, user_text, {**meta_base, "role": "user"})
    if isinstance(assistant_text, str) and assistant_text.strip():
        supermemory_add_document(api_key, container_tag, assistant_text, {**meta_base, "role": "assistant"})

def invoke_bedrock(messages, system=None, max_tokens=64000, temperature=1.0, top_p=None, region=None, model_id=None, api_key=None, timeout=3600):
    if not api_key or not isinstance(api_key, str) or not api_key.strip():
        return {"ok": False, "status": 500, "error": {"message": "AWS_BEARER_TOKEN_BEDROCK is not set"}}
    region = (region if isinstance(region, str) and region.strip() else "us-east-1")
    model_id = (model_id if isinstance(model_id, str) and model_id.strip() else "global.anthropic.claude-opus-4-5-20251101-v1:0")
    host = "bedrock-runtime." + region + ".amazonaws.com"
    path = "/model/" + model_id + "/invoke"
    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": int(max_tokens),
        "messages": normalize_messages(messages),
        "temperature": float(temperature)
    }
    if top_p is not None and isinstance(top_p, (int, float)):
        body["top_p"] = float(top_p)
    if isinstance(system, str) and system.strip():
        body["system"] = system
    payload = json.dumps(body)
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": "Bearer " + api_key,
        "x-amz-bedrock-api-version": "2023-10-01"
    }
    conn = http.client.HTTPSConnection(host, timeout=timeout)
    try:
        conn.request("POST", path, body=payload, headers=headers)
        resp = conn.getresponse()
        status = resp.status
        raw = resp.read()
        ctype = resp.getheader("Content-Type", "application/json")
    finally:
        conn.close()
    if int(status) != 200:
        err = _safe_json_loads(raw)
        if err is None:
            err = {"message": raw.decode("utf-8", errors="ignore")}
        return {"ok": False, "status": int(status), "error": err}
    if "application/json" in (ctype or ""):
        data = _safe_json_loads(raw)
        if isinstance(data, dict):
            return {"ok": True, "status": 200, "data": data}
    return {"ok": True, "status": 200, "data": {"raw": raw.decode("utf-8", errors="ignore")}}

def extract_anthropic_text(data):
    if not isinstance(data, dict):
        return str(data)
    content = data.get("content")
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                parts.append(item["text"])
        return "".join(parts)
    raw = data.get("raw")
    if isinstance(raw, str):
        return raw
    return json.dumps(data, ensure_ascii=False)

@app.route("/", methods=["GET"])
def root():
    return send_from_directory(os.getcwd(), "index.html")

@app.route("/api/chat", methods=["POST"])
def api_chat():
    request_id = str(uuid.uuid4())
    api_key = _env("AWS_BEARER_TOKEN_BEDROCK", "").strip()
    region = _env("AWS_REGION", "us-east-1").strip() or "us-east-1"
    model_id = _env("BEDROCK_MODEL_ID", "global.anthropic.claude-opus-4-5-20251101-v1:0").strip() or "global.anthropic.claude-opus-4-5-20251101-v1:0"
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        payload = {}
    client_id = payload.get("client_id")
    if not isinstance(client_id, str) or not client_id.strip():
        client_id = _env("SUPERMEMORY_USER_ID", "").strip() or str(uuid.uuid4())
    messages = payload.get("messages")
    prompt = payload.get("prompt")
    system = payload.get("system")
    if not isinstance(messages, list) or len(messages) == 0:
        if isinstance(prompt, str) and prompt.strip():
            messages = [{"role": "user", "content": prompt}]
        else:
            return jsonify({"error": "messages or prompt is required", "request_id": request_id}), 400
    last_user = _extract_last_user_text(messages)
    memory_block = ""
    if supermemory_enabled() and isinstance(last_user, str) and last_user.strip():
        memory_block = build_memory_block(client_id, last_user.strip())
    system_base = system if isinstance(system, str) else ""
    system_full = ""
    if memory_block:
        system_full = memory_block + "\n\n" + system_base
    else:
        system_full = system_base
    result = invoke_bedrock(
        messages=messages,
        system=system_full,
        max_tokens=int(_env("MAX_TOKENS", "64000") or "64000"),
        temperature=float(_env("TEMPERATURE", "1.0") or "1.0"),
        top_p=None,
        region=region,
        model_id=model_id,
        api_key=api_key,
        timeout=int(_env("BEDROCK_TIMEOUT", "3600") or "3600")
    )
    if not result.get("ok"):
        status = int(result.get("status") or 500)
        return jsonify({"error": result.get("error"), "status": status, "request_id": request_id}), status
    data = result.get("data", {})
    text = extract_anthropic_text(data)
    store_turn_to_supermemory(client_id, last_user, text, request_id)
    usage = {}
    if isinstance(data, dict) and isinstance(data.get("usage"), dict):
        usage = data["usage"]
    return jsonify({"output_text": text, "usage": usage, "model_id": model_id, "region": region, "request_id": request_id, "client_id": client_id})

if __name__ == "__main__":
    port = int(_env("PORT", "8000") or "8000")
    app.run(host="0.0.0.0", port=port)
