    if max_tokens < 1:
        max_tokens = 1
    if max_tokens > 64000:
        max_tokens = 64000
    sampling_mode = env_str("SAMPLING_MODE", "temperature").lower()
    temperature = env_float("TEMPERATURE", 1.0)
    top_p = env_float("TOP_P", 1.0)
