    if isinstance(system, str) and system.strip():
        body["system"] = system
    if sampling_mode == "top_p":
        body["top_p"] = float(top_p)
    else:
        body["temperature"] = float(temperature)
    headers = {
        "Authorization": "Bearer " + api_key,
        "Accept": "application/json",
        "Content-Type": "application/json; charset=utf-8",
        "User-Agent": "replit-flask-bedrock-supermemory/1.0",
        "Connection": "close"
    }
    timeout = env_int("BEDROCK_TIMEOUT", 3600)
    res = http_request_json(host, "POST", path, headers, body_obj=body, timeout=timeout)
    if not res["ok"]:
        err = res["json"]
        if err is None:
            err = {"message": res["raw"].decode("utf-8", errors="replace")}
        return {"ok": False, "status": res["status"], "error": err}
    if not isinstance(res["json"], dict):
        return {"ok": False, "status": 502, "error": {"message": "Invalid JSON response from Bedrock"}}
    return {"ok": True, "status": res["status"], "data": res["json"], "model_id": model_id, "region": region, "client_id": client_id}

def extract_anthropic_text(data):
    if not isinstance(data, dict):
        return ""
    content = data.get("content", None)
    if not isinstance(content, list):
        return ""
    parts = []
    for item in content:
        if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
            parts.append(item["text"])
    return "".join(parts)

def require_app_token(req):
    token = env_str("APP_AUTH_TOKEN", "")
    if not token:
        return True
    provided = req.headers.get("X-App-Token", "")
    if not isinstance(provided, str):
        provided = str(provided)
    provided = provided.strip()
    return provided == token

@app.after_request
def set_security_headers(resp):
    resp.headers.setdefault("X-Content-Type-Options", "nosniff")
    resp.headers.setdefault("Referrer-Policy", "no-referrer")
    resp.headers.setdefault("X-Frame-Options", "DENY")
    resp.headers.setdefault("Cache-Control", "no-store")
    return resp

@app.route("/", methods=["GET"])
def root():
    if not os.path.isfile(INDEX_PATH):
        abort(404)
    return send_file(INDEX_PATH)

@app.route("/api/chat", methods=["POST"])
def api_chat():
    start_ms = now_monotonic_ms()
    if not require_app_token(request):
        return jsonify({"error": {"message": "Unauthorized"}}), 401
    if request.content_type is None or "application/json" not in request.content_type.lower():
        return jsonify({"error": {"message": "Content-Type must be application/json"}}), 415
    payload = request.get_json(silent=False)
    if not isinstance(payload, dict):
        return jsonify({"error": {"message": "JSON body must be an object"}}), 400
    client_id = payload.get("client_id", "")
    if not isinstance(client_id, str) or not client_id.strip():
        return jsonify({"error": {"message": "client_id required"}}), 400
    client_id = client_id.strip()
    messages = payload.get("messages", None)
    prompt = payload.get("prompt", None)
    system = payload.get("system", "")
    if not isinstance(messages, list) or len(messages) == 0:
        if isinstance(prompt, str) and prompt.strip():
            messages = [{"role": "user", "content": prompt.strip()}]
        else:
            return jsonify({"error": {"message": "messages or prompt required"}}), 400
    request_id = str(uuid.uuid4())
    last_user = extract_last_user_text(messages)
    memories = []
    if supermemory_enabled() and isinstance(last_user, str) and last_user.strip():
        sm = supermemory_search_memories(client_id, last_user.strip())
        if sm.get("ok"):
            memories = sm.get("memories", [])
    system_full = build_system_with_memory(system, memories)
    bedrock = bedrock_invoke(messages, system_full, client_id)
    if not bedrock.get("ok"):
        status = int(bedrock.get("status") or 500)
        latency = now_monotonic_ms() - start_ms
        return jsonify({"error": bedrock.get("error"), "status": status, "request_id": request_id, "latency_ms": latency}), status
    data = bedrock.get("data", {})
    text = extract_anthropic_text(data)
    usage = data.get("usage", {}) if isinstance(data, dict) and isinstance(data.get("usage", None), dict) else {}
    if supermemory_enabled():
        custom_id = sanitize_container_tag("conv_" + client_id)
        if not custom_id:
            custom_id = "conv_" + str(uuid.uuid4())
        turn = "user: " + (last_user if isinstance(last_user, str) else "") + "\nassistant: " + (text if isinstance(text, str) else "")
        meta = {"request_id": request_id, "ts_ms": now_epoch_ms(), "type": "chat_turn"}
        supermemory_add_turn(client_id, custom_id, turn, meta)
    latency = now_monotonic_ms() - start_ms
    return jsonify({"output_text": text, "usage": usage, "request_id": request_id, "latency_ms": latency})

app.config["MAX_CONTENT_LENGTH"] = env_int("MAX_REQUEST_BYTES", 2 * 1024 * 1024)

if __name__ == "__main__":
    port = env_int("PORT", 8000)
    app.run(host="0.0.0.0", port=port, threaded=True)
